internal object AuthUpdateAuthOrganizationPluginOperation {
    /**
     * Updates the organization plugin configuration for Neon Auth. The organization plugin enables multi-tenant organization support.
     *
     * @param projectId The Neon project ID
     * @param branchId The Neon branch ID
     * @param enabled Controls whether the organization plugin is active for the
     *   organization.
     * @param organizationLimit Maximum organizations a user can belong to (created
     *   or joined). At the limit, the user cannot create or join more.
     * @param membershipLimit Maximum members per organization.
     * @param creatorRole Role of the organization's creator. `owner`: full control,
     *   including deleting the org and transferring ownership. `admin`: manage members
     *   and settings only.
     * @param sendInvitationEmail When true, invited users receive an email
     *   containing an accept link. Requires that the invited user has a verified email
     *   address.
     */
    fun updateAuthOrganizationPlugin(clientConfig: ClientConfig, request: Auth.UpdateAuthOrganizationPluginRequest, options: RequestOptions? = null): NeonAuthOrganizationConfig {
        validateUpdateAuthOrganizationPluginRequest(request)

        return SdkClient.request<NeonAuthOrganizationConfig>(SdkClient.RequestSpec("PATCH", "/projects/${SdkClient.encodePathSegment(request.projectId)}/branches/${SdkClient.encodePathSegment(request.branchId)}/auth/plugins/organization", config = clientConfig, body = SdkClient.bodyMap("enabled" to (SdkClient.omitIfNull(request.enabled)), "organization_limit" to
    (SdkClient.omitIfNull(request.organizationLimit)), "membership_limit" to
    (SdkClient.omitIfNull(request.membershipLimit)), "creator_role" to
    (SdkClient.omitIfNull(request.creatorRole)), "send_invitation_email" to
    (SdkClient.omitIfNull(request.sendInvitationEmail))), operationId = "updateAuthOrganizationPlugin", decoder = SdkClient.ResponseDecoder.JSON, options = options, errors = mapOf("default" to GeneralError::class.java))).data
    }


    private fun validateUpdateAuthOrganizationPluginRequest(request: Auth.UpdateAuthOrganizationPluginRequest) {
        Validation.validatePattern("project_id", request.projectId, "^[a-z0-9-]{1,60}$")

        Validation.validatePattern("branch_id", request.branchId, "^[a-z0-9-]{1,60}$")

        if (request.organizationLimit != null) {
            Validation.validateRange("organization_limit", request.organizationLimit, Validation.RangeOpts(min = 1.0))
}

        if (request.membershipLimit != null) {
            Validation.validateRange("membership_limit", request.membershipLimit, Validation.RangeOpts(min = 1.0))
}
    }
}

